  `user_id` int(10) unsigned NOT NULL,
  `name` varchar(200) NOT NULL,
  `slug` varchar(200) DEFAULT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `brand_colors` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Paleta de colores de marca {"primary":"#xxx","secondary":"#xxx","accent":"#xxx"}' CHECK (json_valid(`brand_colors`)),
  `address` varchar(500) DEFAULT NULL,
