DROP TABLE IF EXISTS `templates`;
CREATE TABLE `templates` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `category` enum('dinner','lunch','drinks','cocktails','desserts','brunch','kids','seasonal') NOT NULL DEFAULT 'dinner',
  `dimensions` enum('A4','letter','trifold','bifold','mobile_qr','square') NOT NULL DEFAULT 'A4',
  `width_mm` decimal(8,2) NOT NULL DEFAULT 210.00,
  `height_mm` decimal(8,2) NOT NULL DEFAULT 297.00,
  `layout_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Estructura base de la plantilla (posiciones, secciones, estilos por defecto)' CHECK (json_valid(`layout_json`)),
  `style_defaults_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Estilos tipográficos y de color por defecto' CHECK (json_valid(`style_defaults_json`)),
  `thumbnail_url` varchar(500) DEFAULT NULL,
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_templates_category` (`category`),
  KEY `idx_templates_dimensions` (`dimensions`),
  KEY `idx_templates_premium` (`is_premium`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

