ottom\":30,\"left\":25},\"showDividers\":true,\"dividerStyle\":\"glow\"},\"dishBlock\":{\"showPriceLeaders\":false,\"leaderChar\":\"\",\"showDescription\":true,\"showAllergens\":true,\"showImages\":false,\"pricePosition\":\"right\"}}', NULL, '0', '11', '2026-09-24 09:05:16');

DROP TABLE IF EXISTS `menus`;
CREATE TABLE `menus` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `restaurant_id` int(10) unsigned NOT NULL,
  `template_id` int(10) unsigned DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `style_config_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Configuración visual: tipografías, colores, fondos, layout, opciones de bloques' CHECK (json_valid(`style_config_json`)),
  `content_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Contenido estructurado: secciones, platillos, precios, alérgenos, badges' CHECK (json_valid(`content_json`)),
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_menus_restaurant` (`restaurant_id`),
  KEY `idx_menus_template` (`template_id`),
  KEY `idx_menus_status` (`status`),
  CONSTRAINT `fk_menus_restaurant` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_menus_template` FOREIGN KEY (`template_id`) REFERENCES `templates` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

