DROP TABLE IF EXISTS `custom_fonts`;
CREATE TABLE `custom_fonts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `restaurant_id` int(10) unsigned DEFAULT NULL COMMENT 'NULL = fuente global del sistema',
  `font_name` varchar(150) NOT NULL,
  `font_family` varchar(150) NOT NULL,
  `font_file_path` varchar(500) NOT NULL,
  `font_format` enum('woff2','woff','ttf','otf') NOT NULL DEFAULT 'woff2',
  `font_weight` varchar(20) NOT NULL DEFAULT '400',
  `font_style` enum('normal','italic') NOT NULL DEFAULT 'normal',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_fonts_restaurant` (`restaurant_id`),
  KEY `idx_fonts_family` (`font_family`),
  CONSTRAINT `fk_fonts_restaurant` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `media_assets`;
CREATE TABLE `media_assets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `restaurant_id` int(10) unsigned NOT NULL,
  `type` enum('logo','background','icon','dish_photo','texture','decorative') NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `mime_type` varchar(50) DEFAULT NULL,
  `file_size` int(10) unsigned DEFAULT NULL COMMENT 'Tamaño en bytes',
  `width` int(10) unsigned DEFAULT NULL,
  `height` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_media_restaurant` (`restaurant_id`),
  KEY `idx_media_type` (`type`),
  CONSTRAINT `fk_media_restaurant` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

